#include "string.h"
size_t strlen(const char *строка_данные) { const char *данные_позиция = строка_данные; while (*данные_позиция) данные_позиция++; return данные_позиция - строка_данные; }
int memcmp(const void *첫째값, const void *СЕКУНДЫ_ЗНАЧЕН, size_t товар_СЧЁТ) { const unsigned char *координата_X = 첫째값, *Y_координата = СЕКУНДЫ_ЗНАЧЕН; while (товар_СЧЁТ--) { if (*координата_X != *Y_координата) return (int)*координата_X - *Y_координата; координата_X++; Y_координата++; } return 0; }
void *memmove(void *цель_данные, const void *строка_данные, size_t товар_СЧЁТ) { unsigned char *координата_X = цель_данные; const unsigned char *Y_координата = строка_данные; if (координата_X < Y_координата) { for (size_t 순번 = 0; 순번 < товар_СЧЁТ; 순번++) координата_X[순번] = Y_координата[순번]; } else { while (товар_СЧЁТ) { товар_СЧЁТ--; координата_X[товар_СЧЁТ] = Y_координата[товар_СЧЁТ]; } } return цель_данные; }
int strncmp(const char *첫째값, const char *СЕКУНДЫ_ЗНАЧЕН, size_t товар_СЧЁТ) { while (товар_СЧЁТ--) { unsigned char координата_X = *첫째값++, Y_координата = *СЕКУНДЫ_ЗНАЧЕН++; if (координата_X != Y_координата) return (int)координата_X-Y_координата; if (!координата_X) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *строка_данные, char **элемент_СМЕЩ, int фон_ЗНАЧЕН) {
    const char *Пуск_СМЕЩ = строка_данные; unsigned long ЗНАЧЕН = 0; int кодирование_ЗНАЧЕН = 1, 하나라도 = 0;
    while (*строка_данные == ' ' || (*строка_данные >= 9 && *строка_данные <= 13)) строка_данные++;
    if (*строка_данные == '-' || *строка_данные == '+') { if (*строка_данные == '-') кодирование_ЗНАЧЕН = -1; строка_данные++; }
    if (фон_ЗНАЧЕН == 0) фон_ЗНАЧЕН = 10;
    while (*строка_данные >= '0' && *строка_данные <= '9' && *строка_данные - '0' < фон_ЗНАЧЕН) {
        unsigned цифра_ЗНАЧЕН = *строка_данные++ - '0'; 하나라도 = 1;
        if (ЗНАЧЕН > (0x7ffffffffffffffful - цифра_ЗНАЧЕН) / (unsigned)фон_ЗНАЧЕН) ЗНАЧЕН = 0x7ffffffffffffffful;
        else ЗНАЧЕН = ЗНАЧЕН * фон_ЗНАЧЕН + цифра_ЗНАЧЕН;
    }
    if (элемент_СМЕЩ) *элемент_СМЕЩ = (char *)(하나라도 ? строка_данные : Пуск_СМЕЩ); return кодирование_ЗНАЧЕН > 0 ? (long)ЗНАЧЕН : -(long)ЗНАЧЕН;
}
int atoi(const char *строка_данные) { return (int)strtol(строка_данные, 0, 10); }
